    private func star() throws -> CADDocument {
        try JSONDecoder().decode(CADDocument.self, from: Data(Self.star.utf8))
    }

    private func outline(_ doc: CADDocument) throws -> [String] {
        let body = try #require(Regenerator.regenerate(doc).body("e4627c46"))
        return try body.loopEdges(face: "e4627c46.end", edge: "e4627c46.end|e4627c46.side.845eb1f1")
    }

    @Test func theOutlineCanBeChamferedAlthoughTheBodyHasSlits() throws {
        let doc = try star()
        let edges = try outline(doc)
        #expect(edges.count == 18, "six arcs and twelve sides: \(edges.count)")
        let before = try #require(Regenerator.regenerate(doc).body("e4627c46")).volume
        for size in ["0.5 mm", "2 mm"] {
            var d = doc
            d.features.append(Feature(id: "c", name: "Chamfer1", .chamfer(EdgeFeature(edges: edges.map { EdgeRef(body: "e4627c46", edge: $0) }, size: size))))
            let r = Regenerator.regenerate(d)
            #expect(r.errors.isEmpty, "a \(size) chamfer of the outline: \(r.errors)")
            let after = try #require(r.body("e4627c46")).volume
            let width = size == "0.5 mm" ? 0.5 : 2.0
            let bevel = 830 * width * width / 2  // the outline is about 830 mm long
            #expect(abs((before - after) - bevel) < 0.05 * bevel, "\(size): \(before - after) came off, expected about \(bevel)")
        }
    }

    @Test func aRoundOfTheOutlineWorksToo() throws {
        let doc = try star()
        var d = doc
        d.features.append(Feature(id: "f", name: "Fillet1", .fillet(EdgeFeature(edges: try outline(doc).map { EdgeRef(body: "e4627c46", edge: $0) }, size: "2 mm"))))
        let r = Regenerator.regenerate(d)
        #expect(r.errors.isEmpty, "\(r.errors)")
    }
}
